dslRule:
java.lang.StringBuffer $var = new java.lang.StringBuffer($args$);
=> java.lang.StringBuilder $var = new java.lang.StringBuilder($args$);
;;

beforeExample:
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;

public class Example {
    void readFile(InputStream contentStream, String encoding, int BUFFER_SIZE) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(contentStream, encoding), BUFFER_SIZE);
        java.lang.StringBuffer buffer = new java.lang.StringBuffer(BUFFER_SIZE);
        char[] readBuffer = new char[1024];
        int n = in.read(readBuffer);
        while (n > 0) {
            buffer.append(readBuffer, 0, n);
            n = in.read(readBuffer);
        }
        in.close();
    }
}

